input.command:
python3 - <<'E'
p='css/pages.css'
s=open(p).read()
a=""".plan-ribbon {
  position: absolute;"""
n=""".plan-featured .btn-primary {
  background: var(--color-success);
  color: #ffffff;
}

.plan-featured .btn-primary:hover {
  background: color-mix(in srgb, var(--color-success) 85%, #000000);
}

"""
assert a in s
open(p,'w').write(s.replace(a,n+a,1))
E
cd .. && npx playwright test tests/functional.spec.ts 2>&1 | tail -5

